import json
import os
from decimal import Decimal, InvalidOperation
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


STANDARD_SCHEMA_VERSION = "1.0"
AZURE_MODEL_ID = "prebuilt-invoice"


def _to_decimal_string(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, dict):
        for key in ("amount", "value", "text", "content"):
            if key in value:
                return _to_decimal_string(value[key])
    try:
        return str(Decimal(str(value)))
    except (InvalidOperation, ValueError, TypeError):
        return None


def _first_non_empty(*values: Any) -> Optional[str]:
    for value in values:
        if value is None:
            continue
        if isinstance(value, str):
            if value.strip():
                return value.strip()
        else:
            text = str(value).strip()
            if text:
                return text
    return None


def _field_content(field: Any) -> Any:
    if field is None:
        return None
    if hasattr(field, "value") and field.value is not None:
        return field.value
    if hasattr(field, "content") and field.content is not None:
        return field.content
    return field


def _currency_code_from_field(field: Any) -> Optional[str]:
    value = _field_content(field)
    if value is None:
        return None
    if hasattr(value, "currency_code"):
        return value.currency_code
    if isinstance(value, dict):
        return value.get("currencyCode") or value.get("currency_code")
    return None


def _amount_from_field(field: Any) -> Optional[str]:
    value = _field_content(field)
    if value is None:
        return None
    if hasattr(value, "amount"):
        return _to_decimal_string(value.amount)
    if isinstance(value, dict):
        return _to_decimal_string(value.get("amount") or value.get("value"))
    return _to_decimal_string(value)


def _date_from_field(field: Any) -> Optional[str]:
    value = _field_content(field)
    if value is None:
        return None
    if hasattr(value, "isoformat"):
        return value.isoformat()
    return _first_non_empty(value)


def _address_to_string(address_value: Any) -> Optional[str]:
    if address_value is None:
        return None
    if isinstance(address_value, str):
        return address_value.strip() or None

    parts = []
    for attr in (
        "house_number",
        "road",
        "city",
        "state",
        "postal_code",
        "country_region",
        "street_address",
        "unit",
        "city_district",
        "state_district",
        "suburb",
        "po_box",
    ):
        if hasattr(address_value, attr):
            v = getattr(address_value, attr)
            if v:
                parts.append(str(v).strip())

    if not parts and hasattr(address_value, "content") and address_value.content:
        return address_value.content.strip() or None

    if not parts and isinstance(address_value, dict):
        for key in (
            "streetAddress",
            "houseNumber",
            "road",
            "city",
            "state",
            "postalCode",
            "countryRegion",
        ):
            v = address_value.get(key)
            if v:
                parts.append(str(v).strip())

    result = ", ".join([p for p in parts if p])
    return result or None


def _normalize_line_items(items_field: Any) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    items = _field_content(items_field)
    if not items:
        return normalized

    for item in items:
        value = _field_content(item)
        if not value:
            continue

        fields = getattr(value, "value", None)
        if fields is None and isinstance(value, dict):
            fields = value

        if not fields:
            continue

        description = None
        quantity = None
        unit_price = None
        amount = None
        product_code = None
        unit = None

        if isinstance(fields, dict):
            description = _first_non_empty(
                _field_content(fields.get("Description")),
                _field_content(fields.get("ProductCode")),
            )
            quantity = _to_decimal_string(_field_content(fields.get("Quantity")))
            unit_price = _amount_from_field(fields.get("UnitPrice"))
            amount = _amount_from_field(fields.get("Amount"))
            product_code = _first_non_empty(_field_content(fields.get("ProductCode")))
            unit = _first_non_empty(_field_content(fields.get("Unit")))

        normalized.append(
            {
                "description": description,
                "quantity": quantity,
                "unit_price": unit_price,
                "amount": amount,
                "product_code": product_code,
                "unit": unit,
            }
        )

    return normalized


def normalize_expense_fields(document_bytes: bytes) -> str:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    poller = client.begin_analyze_document(
        model_id=AZURE_MODEL_ID,
        body=document_bytes,
    )
    result = poller.result()

    doc = result.documents[0] if result.documents else None
    fields = getattr(doc, "fields", {}) if doc else {}

    vendor_name = _first_non_empty(_field_content(fields.get("VendorName")))
    customer_name = _first_non_empty(_field_content(fields.get("CustomerName")))
    invoice_id = _first_non_empty(_field_content(fields.get("InvoiceId")))
    purchase_order = _first_non_empty(_field_content(fields.get("PurchaseOrder")))
    invoice_date = _date_from_field(fields.get("InvoiceDate"))
    due_date = _date_from_field(fields.get("DueDate"))
    payment_term = _first_non_empty(_field_content(fields.get("PaymentTerm")))

    vendor_address = _address_to_string(_field_content(fields.get("VendorAddress")))
    customer_address = _address_to_string(_field_content(fields.get("CustomerAddress")))

    subtotal = _amount_from_field(fields.get("SubTotal"))
    total_tax = _amount_from_field(fields.get("TotalTax"))
    invoice_total = _amount_from_field(fields.get("InvoiceTotal"))
    amount_due = _amount_from_field(fields.get("AmountDue"))
    previous_unpaid_balance = _amount_from_field(fields.get("PreviousUnpaidBalance"))

    currency = _first_non_empty(
        _currency_code_from_field(fields.get("InvoiceTotal")),
        _currency_code_from_field(fields.get("AmountDue")),
        _currency_code_from_field(fields.get("SubTotal")),
        _currency_code_from_field(fields.get("TotalTax")),
    )

    line_items = _normalize_line_items(fields.get("Items"))

    output: Dict[str, Any] = {
        "schema_version": STANDARD_SCHEMA_VERSION,
        "provider": {
            "name": "azure-document-intelligence",
            "model_id": AZURE_MODEL_ID,
        },
        "document": {
            "doc_type": "invoice",
            "invoice_id": invoice_id,
            "purchase_order": purchase_order,
            "invoice_date": invoice_date,
            "due_date": due_date,
            "payment_term": payment_term,
        },
        "vendor": {
            "name": vendor_name,
            "address": vendor_address,
        },
        "customer": {
            "name": customer_name,
            "address": customer_address,
        },
        "amounts": {
            "currency": currency,
            "subtotal": subtotal,
            "tax": total_tax,
            "total": invoice_total,
            "amount_due": amount_due,
            "previous_unpaid_balance": previous_unpaid_balance,
        },
        "line_items": line_items,
        "raw_metadata": {
            "document_count": len(result.documents or []),
            "content_format": getattr(result, "content_format", None),
        },
    }

    return json.dumps(output, ensure_ascii=False, indent=2)
